-- App-wide settings, held as a single row (id 1). The default tax rate is the sales tax percentage a
-- new invoice starts with; it starts at zero (no tax).
CREATE TABLE app_settings (
    id BIGINT PRIMARY KEY,
    default_tax_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL,
    CONSTRAINT app_settings_single_row CHECK (id = 1),
    CONSTRAINT app_settings_default_tax_pct_range CHECK (default_tax_pct >= 0 AND default_tax_pct <= 100)
);

INSERT INTO app_settings (id, default_tax_pct) VALUES (1, 0);
-- Each client is billed in their own currency (ISO 4217 code); existing clients keep US dollars.
ALTER TABLE client ADD COLUMN currency VARCHAR(3) DEFAULT 'USD' NOT NULL;
ALTER TABLE client ADD CONSTRAINT client_currency_known CHECK (currency IN ('USD', 'EUR', 'GBP', 'CAD', 'AUD'));
-- Unused credit (held deposits and unused credit notes) paid back to a client. A refund draws on
-- the held deposits first and then on unused credit notes; the split is kept so each part of the
-- client's credit drops by exactly what was refunded from it.
CREATE TABLE refund (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id         BIGINT         NOT NULL,
    amount            DECIMAL(12, 2) NOT NULL,
    from_deposits     DECIMAL(12, 2) NOT NULL,
    from_credit_notes DECIMAL(12, 2) NOT NULL,
    refunded_on       DATE           NOT NULL,
    note              VARCHAR(500),
    CONSTRAINT refund_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    CONSTRAINT refund_amount_positive CHECK (amount > 0),
    CONSTRAINT refund_split_matches CHECK (from_deposits >= 0 AND from_credit_notes >= 0
        AND from_deposits + from_credit_notes = amount)
);

CREATE INDEX refund_client_idx ON refund (client_id, refunded_on);
-- A lump payment can now use up the client's credit first: part of what it settles may come out of their held
-- deposits (from_deposits) and then their unused credit notes (from_credit_notes), on top of the money received.
-- Whatever of the money received is not needed for the invoices is kept as credit for the client (to_credit) and
-- is held alongside their deposits. The payments recorded against the invoices always add up to
-- amount + from_deposits + from_credit_notes - to_credit.
ALTER TABLE client_payment ADD COLUMN from_deposits DECIMAL(12, 2) DEFAULT 0 NOT NULL;
ALTER TABLE client_payment ADD COLUMN from_credit_notes DECIMAL(12, 2) DEFAULT 0 NOT NULL;
ALTER TABLE client_payment ADD COLUMN to_credit DECIMAL(12, 2) DEFAULT 0 NOT NULL;
ALTER TABLE client_payment ADD CONSTRAINT client_payment_credit_split CHECK (from_deposits >= 0
    AND from_credit_notes >= 0 AND to_credit >= 0 AND to_credit <= amount);
-- The currencies clients can be billed in, each with the symbol its amounts are shown with and the step
-- its amounts are rounded to when shown (0.01 rounds to the cent; 0.05 to the nearest five cents).
CREATE TABLE currency (
    code VARCHAR(3) PRIMARY KEY,
    symbol VARCHAR(8) NOT NULL,
    rounding_step DECIMAL(10, 2) DEFAULT 0.01 NOT NULL,
    CONSTRAINT currency_rounding_step_positive CHECK (rounding_step > 0)
);

