package net.officefloor.hq.app.settings;

import jakarta.validation.Valid;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/settings")
public class SettingsController {

    private final SettingsService service;

    public SettingsController(SettingsService service) {
        this.service = service;
    }

    @GetMapping
    public SettingsResponse get() {
        return service.get();
    }

    @PutMapping
    public SettingsResponse update(@Valid @RequestBody SettingsRequest request) {
        return service.update(request);
    }
}
package net.officefloor.hq.app.settings;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;

/** The app-wide settings, stored as a single row with id {@link #ID}. */
@Entity
@Table(name = "app_settings")
public class Settings {

    /** The id of the one settings row. */
    public static final long ID = 1L;

    @Id
    private Long id;

    /** The sales tax percentage a new invoice starts with. */
    @Column(name = "default_tax_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal defaultTaxPct = BigDecimal.ZERO.setScale(2);

    protected Settings() {
    }

    public BigDecimal getDefaultTaxPct() {
        return defaultTaxPct;
    }

    public void setDefaultTaxPct(BigDecimal defaultTaxPct) {
        this.defaultTaxPct = defaultTaxPct.setScale(2, RoundingMode.HALF_UP);
    }
}
package net.officefloor.hq.app.settings;

import org.springframework.data.jpa.repository.JpaRepository;

public interface SettingsRepository extends JpaRepository<Settings, Long> {
}
package net.officefloor.hq.app.settings;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;

/** Payload to change the app-wide settings: the sales tax percentage new invoices start with. */
public record SettingsRequest(
        @NotNull @DecimalMin("0") @DecimalMax("100") @Digits(integer = 3, fraction = 2) BigDecimal defaultTaxPct) {
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;

public record SettingsResponse(BigDecimal defaultTaxPct) {

    public static SettingsResponse from(Settings settings) {
        return new SettingsResponse(settings.getDefaultTaxPct());
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SettingsService {

    private final SettingsRepository settings;

    public SettingsService(SettingsRepository settings) {
        this.settings = settings;
    }

    @Transactional(readOnly = true)
    public SettingsResponse get() {
        return SettingsResponse.from(find());
    }

    @Transactional
    public SettingsResponse update(SettingsRequest request) {
        Settings current = find();
        current.setDefaultTaxPct(request.defaultTaxPct());
        settings.flush();
        return SettingsResponse.from(current);
    }

    /** The sales tax percentage a new invoice starts with when none is given for it. */
    @Transactional(readOnly = true)
    public BigDecimal defaultTaxPct() {
        return find().getDefaultTaxPct();
    }

    private Settings find() {
        return settings.findById(Settings.ID)
                .orElseThrow(() -> new IllegalStateException("The settings row is missing"));
    }
}
package net.officefloor.hq.app.currency;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Comparator;
import java.util.List;

/**
 * A currency clients can be billed in, by ISO 4217 code, with the symbol its amounts are shown with and
 * the step they are rounded to when shown (0.05 rounds to the nearest five cents), and the number of
 * decimal places they are shown with (yen has none).
 */
@Entity
@Table(name = "currency")
public class Currency {

    /** The currency a client is billed in unless another is chosen. */
    public static final String DEFAULT = "USD";

    /** The original currencies come first in their usual order; any others follow by code. */
    private static final List<String> STANDARD = List.of("USD", "EUR", "GBP", "CAD", "AUD");

    public static final Comparator<String> ORDER = Comparator
            .comparingInt((String code) -> STANDARD.contains(code) ? STANDARD.indexOf(code) : STANDARD.size())
            .thenComparing(Comparator.naturalOrder());

    @Id
    private String code;

    @Column(nullable = false)
    private String symbol;

    @Column(name = "rounding_step", nullable = false, precision = 10, scale = 2)
    private BigDecimal roundingStep = new BigDecimal("0.01");

    @Column(nullable = false)
    private int decimals = 2;

    protected Currency() {
    }

    public String getCode() {
        return code;
    }

    public String getSymbol() {
        return symbol;
    }

    public BigDecimal getRoundingStep() {
        return roundingStep;
    }

    public int getDecimals() {
        return decimals;
    }

    public void setRoundingStep(BigDecimal roundingStep) {
        this.roundingStep = roundingStep.setScale(2, RoundingMode.HALF_UP);
    }
}
package net.officefloor.hq.app.currency;

import org.springframework.data.jpa.repository.JpaRepository;

public interface CurrencyRepository extends JpaRepository<Currency, String> {
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/**
 * A single invoice together with the line items it is built from: their subtotal, each discount on it
 * (with what it takes off), the percentage discounts and flat amount discounts added up, and what they all take off together, the sales tax percentage, the taxable base it is charged on (the
 * taxable lines after the discount) and what it adds, the levy (second tax) percentage and what it adds
 * on the same base, any flat surcharge (such as a handling fee) added after tax, the amount owed including both taxes and the surcharge, the total before tax, whether the prices already include the taxes
 * (so they are worked back out rather than added on), whether the client is tax exempt (so
 * there is no tax at all), the effective tax rate (the sales tax and levy together as a percentage of
 * the total before tax), any early-payment discount offered (its percentage, the days after issue it
 * must be paid within, the last day to pay, and the reduced amount; null when none is offered), and the
 * client's tax number (null when the client is not tax registered), the minimum charge, the net total
 * before it, whether the minimum was billed because the net total came out under it, and the total
 * savings (the line discounts and the invoice's discounts added together).
 */
public record InvoiceDetailResponse(Long id, Long projectId, String currency, BigDecimal amount, BigDecimal totalExTax,
        BigDecimal subtotal,
        BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discount, BigDecimal taxPct, BigDecimal taxableBase, BigDecimal tax,
        BigDecimal levyPct, BigDecimal levy, BigDecimal surcharge, boolean taxInclusive, boolean taxExempt, BigDecimal effectiveTaxPct,
        BigDecimal earlyPaymentPct, int earlyPaymentDays, LocalDate earlyPaymentBy, BigDecimal earlyPaymentAmount,
        InvoiceStatus status, LocalDate issuedDate,
        LocalDate dueDate, List<LineItemResponse> lineItems, String clientTaxNumber, List<InvoiceDiscountResponse> discounts,
        BigDecimal minimumCharge, BigDecimal netTotal, boolean minimumApplied, BigDecimal totalSavings) {

    static InvoiceDetailResponse from(Invoice invoice) {
        return from(invoice, invoice.getStatus());
    }

    /** The invoice with the given status, as worked out from what has been paid and credited against it. */
    static InvoiceDetailResponse from(Invoice invoice, InvoiceStatus status) {
        return new InvoiceDetailResponse(invoice.getId(), invoice.getProject().getId(),
                invoice.getProject().getClient().getCurrency(), invoice.getAmount(), invoice.getTotalExTax(),
                invoice.getSubtotal(), invoice.getDiscountPct(), invoice.getDiscountAmount(), invoice.getDiscount(),
                invoice.getTaxPct(), invoice.getTaxableBase(), invoice.getTax(),
                invoice.getLevyPct(), invoice.getLevy(), invoice.getSurcharge(), invoice.isTaxInclusive(), invoice.isTaxExempt(),
                invoice.getEffectiveTaxPct(),
                invoice.getEarlyPaymentPct(), invoice.getEarlyPaymentDays(), invoice.getEarlyPaymentBy(),
                invoice.getEarlyPaymentAmount(),
                status, invoice.getIssuedDate(), invoice.getDueDate(),
                invoice.getLineItems().stream().map(LineItemResponse::from).toList(),
                invoice.getProject().getClient().getTaxNumber(),
                invoice.getDiscounts().stream().map(d -> new InvoiceDiscountResponse(d.getId(), d.getDiscountPct(),
                        d.getDiscountAmount(), d.getDiscountCap(), invoice.discountTakenBy(d))).toList(),
                invoice.getMinimumCharge(), invoice.getNetTotal(), invoice.isMinimumApplied(),
                invoice.getTotalSavings());
    }
}
